<script>
  import { resizeObserver } from '@splendidlabz/utils/dom'
  import { onMount } from 'svelte'

  let klass = ''
  export { klass as class }

  let container
  let colGap
  let items

  onMount(async () => {
    if (isMasonrySupported(container)) return

    items = getChildren(container)
    colGap = parseFloat(getComputedStyle(container).columnGap)
    container.style.setProperty('row-gap', '1px', 'important')
    container.style.gridAutoRows = '0px'

    await Promise.all([areImagesLoaded(), areVideosLoaded()])

    layout()
  })

  function isMasonrySupported(container) {
    if (typeof window === 'undefined') return
    return getComputedStyle(container).gridTemplateRows === 'masonry'
  }

  function getChildren(container) {
    let children = container.children

    // Compensate for Astro Slots
    if (children[0]?.nodeName === 'ASTRO-SLOT') children = children[0].children
    return Array.from(children)
  }

  async function areImagesLoaded() {
    const images = Array.from(container.querySelectorAll('img'))
    const promises = images.map(img => {
      return new Promise((resolve, reject) => {
        if (img.complete) return resolve()
        img.onload = resolve
        img.onerror = reject
      })
    })
    return Promise.all(promises)
  }

  function areVideosLoaded() {
    const videos = Array.from(container.querySelectorAll('video'))
    const promises = videos.map(video => {
      return new Promise((resolve, reject) => {
        if (video.readyState === 4) return resolve() // HAVE_ENOUGH_DATA
        video.onloadedmetadata = resolve
        video.onerror = reject
      })
    })
    return Promise.all(promises)
  }

  async function layout() {
    if (isMasonrySupported(container)) return
    items.forEach(item => {
      const ib = item.getBoundingClientRect()
      item.style.gridRowEnd = `span ${Math.round(ib.height + colGap)}`
    })
  }
</script>

<div
  class="Masonry {klass}"
  {...$$restProps}
  bind:this={container}
  use:resizeObserver
  on:resize={layout}
>
  <slot />
</div>
